#include "ZcsContentStore.h"
#include <cassert>
#include <iostream>
#include <string>
#include <vector>
#include <limits>
using namespace FlashMock;
static int checks=0;
#define CHECK(x) do{++checks;if(!(x))throw std::runtime_error(std::string("check failed line ")+std::to_string(__LINE__)+": "+#x);}while(0)
std::string digest(const std::string& data){uint8_t out[32];mbedtls_sha256_context hash;mbedtls_sha256_init(&hash);mbedtls_sha256_starts(&hash,0);mbedtls_sha256_update(&hash,reinterpret_cast<const uint8_t*>(data.data()),data.size());mbedtls_sha256_finish(&hash,out);char hex[65];for(size_t i=0;i<32;++i)snprintf(hex+i*2,3,"%02x",out[i]);return hex;}
bool put(ZcsContentStore& store,const char* id,const std::string& data){return store.beginPut(id,data.size(),digest(data).c_str())&&store.write(reinterpret_cast<const uint8_t*>(data.data()),data.size())&&store.finish();}
std::string get(ZcsContentStore& store,const char* id){const auto* e=store.find(id);if(!e)return{};std::string s(e->length,'\0');CHECK(store.read(id,0,s.data(),s.size()));return s;}
bool reject(ZcsContentStore& store,void*){char b[3];CHECK(store.readPending(0,b,3));CHECK(!memcmp(b,"new",3));return false;}
void basic(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(s.count()==0&&mutations==0);CHECK(!s.find("missing"));CHECK(put(s,"__logos","RIFFWEBP"));CHECK(put(s,"message","hello"));CHECK(s.count()==2);CHECK(s.usedBytes()==13);CHECK(get(s,"__logos")=="RIFFWEBP");CHECK(get(s,"message")=="hello");ZcsContentStore reboot;CHECK(reboot.begin());CHECK(reboot.count()==2&&get(reboot,"message")=="hello");CHECK(put(reboot,"message","replacement"));CHECK(reboot.count()==2&&get(reboot,"__logos")=="RIFFWEBP");CHECK(get(reboot,"message")=="replacement");CHECK(!reboot.remove("__logos"));CHECK(put(reboot,"__web","gzip"));CHECK(!reboot.remove("__web"));CHECK(!reboot.remove("missing"));CHECK(reboot.remove("message"));CHECK(reboot.count()==2&&get(reboot,"__logos")=="RIFFWEBP");ZcsContentStore r2;CHECK(r2.begin()&&r2.count()==2);}
void bounds(){reset();ZcsContentStore s;CHECK(s.begin());std::string a="a";auto sha=digest(a);for(const char* id:{"","UPPER","a/b",".","é","a b","abcdefghijklmnopqrstuvwxyz1234567"})CHECK(!s.beginPut(id,1,sha.c_str()));CHECK(!s.beginPut(nullptr,1,sha.c_str()));CHECK(!s.beginPut("good",0,sha.c_str()));CHECK(!s.beginPut("good",ZcsContentStore::CAPACITY+1,sha.c_str()));CHECK(!s.beginPut("good",1,"bad"));CHECK(!s.beginPut("good",1,std::string(64,'g').c_str()));CHECK(mutations==0);CHECK(put(s,"abcdefghijklmnopqrstuvwxyz123456","a"));char b;CHECK(!s.read("missing",0,&b,1));CHECK(!s.read("abcdefghijklmnopqrstuvwxyz123456",1,&b,1));CHECK(!s.read("abcdefghijklmnopqrstuvwxyz123456",UINT32_MAX,&b,1));CHECK(!s.read("abcdefghijklmnopqrstuvwxyz123456",0,&b,SIZE_MAX));CHECK(!s.read("abcdefghijklmnopqrstuvwxyz123456",0,nullptr,1));CHECK(s.read("abcdefghijklmnopqrstuvwxyz123456",1,nullptr,0));for(int i=1;i<16;i++)CHECK(put(s,("p"+std::to_string(i)).c_str(),"a"));CHECK(s.count()==16);size_t before=mutations;CHECK(!put(s,"seventeenth","a"));CHECK(mutations==before);CHECK(put(s,"p1","b"));CHECK(s.count()==16);}
void uploadFailures(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"message","old"));auto before=bytes;CHECK(s.beginPut("message",3,digest("new").c_str()));CHECK(!s.beginPut("other",3,digest("new").c_str()));CHECK(s.busy());CHECK(!s.readPending(0,nullptr,1));CHECK(s.write(reinterpret_cast<const uint8_t*>("n"),1));CHECK(!s.finish());CHECK(!s.busy()&&get(s,"message")=="old");CHECK(s.beginPut("message",3,digest("new").c_str()));CHECK(!s.write(reinterpret_cast<const uint8_t*>("long"),4));CHECK(!s.busy());CHECK(s.beginPut("message",3,digest("new").c_str()));CHECK(s.write(reinterpret_cast<const uint8_t*>("bad"),3));CHECK(!s.finish());CHECK(std::string(s.error())=="sha256_mismatch");CHECK(get(s,"message")=="old");CHECK(s.beginPut("message",3,digest("new").c_str()));CHECK(s.write(reinterpret_cast<const uint8_t*>("new"),3));CHECK(!s.finish(reject));CHECK(std::string(s.error())=="content_rejected");CHECK(get(s,"message")=="old");CHECK(s.beginPut("message",3,digest("new").c_str()));s.abort();CHECK(!s.busy());CHECK(!s.write(nullptr,0));CHECK(!s.finish());CHECK(!s.readPending(0,nullptr,0));CHECK(put(s,"message","new"));}
void capacity(){reset();ZcsContentStore s;CHECK(s.begin());std::string full(ZcsContentStore::CAPACITY,'x');CHECK(put(s,"full",full));CHECK(s.usedBytes()==ZcsContentStore::CAPACITY);size_t before=mutations;CHECK(!put(s,"extra","x"));CHECK(mutations==before);CHECK(get(s,"full")==full);CHECK(put(s,"full","small"));CHECK(s.usedBytes()==5);}
void corruption(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"message","old"));CHECK(put(s,"message","new"));auto good=bytes;for(size_t at:{size_t(ZcsContentStore::BANK_BYTES),size_t(ZcsContentStore::BANK_BYTES+8),size_t(ZcsContentStore::BANK_BYTES+52),size_t(ZcsContentStore::BANK_BYTES+ZcsContentStore::HEADER_BYTES)}){bytes=good;bytes[at]^=1;ZcsContentStore reboot;CHECK(reboot.begin());CHECK(get(reboot,"message")=="old");}bytes=good;bytes[ZcsContentStore::BANK_BYTES+ZcsContentStore::HEADER_BYTES]^=1;CHECK(!s.beginPut("other",1,digest("x").c_str()));CHECK(std::string(s.error())=="storage_corrupt");bytes=good;bytes[ZcsContentStore::HEADER_BYTES]^=1;bytes[ZcsContentStore::BANK_BYTES+ZcsContentStore::HEADER_BYTES]^=1;size_t before=mutations;ZcsContentStore empty;CHECK(empty.begin());CHECK(empty.count()==0&&mutations==before);CHECK(put(empty,"fresh","repair"));CHECK(get(empty,"fresh")=="repair");}
void cuts(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"__logos","images"));CHECK(put(s,"message","old"));const auto initial=bytes;mutations=0;CHECK(put(s,"message","new"));const size_t work=mutations;std::vector<size_t> cuts={0,1,4095,4096,8191,8192,8193,8198,8199,work-5,work-4,work-3,work-2,work-1,work};for(size_t point:cuts){bytes=initial;cut=-1;ZcsContentStore working;CHECK(working.begin());cut=point;try{put(working,"message","new");}catch(const PowerLoss&){}cut=-1;ZcsContentStore reboot;CHECK(reboot.begin());auto value=get(reboot,"message");CHECK(value=="old"||value=="new");CHECK(get(reboot,"__logos")=="images");CHECK(put(reboot,"next","recovered"));}bytes=initial;cut=-1;ZcsContentStore probe;CHECK(probe.begin());calls=0;CHECK(put(probe,"message","new"));int operations=calls;for(int failure=1;failure<=operations;++failure){bytes=initial;failCall=-1;calls=0;ZcsContentStore f;CHECK(f.begin());calls=0;failCall=failure;put(f,"message","new");failCall=-1;ZcsContentStore reboot;CHECK(reboot.begin());auto value=get(reboot,"message");CHECK(value=="old"||value=="new");CHECK(get(reboot,"__logos")=="images");}}
void absent(){reset();present=false;ZcsContentStore s;CHECK(!s.begin());CHECK(!s.available());CHECK(!put(s,"a","x"));present=true;part.size=0x150000;CHECK(!s.begin());CHECK(mutations==0);}

uint32_t headerCrc(size_t start){uint32_t crc=0xffffffff;for(size_t i=start+4;i<start+752;++i){crc^=bytes[i];for(int j=0;j<8;++j)crc=(crc>>1)^(0xedb88320U&(0U-(crc&1)));}return ~crc;}
void word(size_t offset,uint32_t value){for(size_t i=0;i<4;++i)bytes[offset+i]=uint8_t(value>>(8*i));}
void refreshCrc(size_t bank){word(bank+752,headerCrc(bank));}
void forgedHeaders(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"old","A"));CHECK(put(s,"new","B"));auto good=bytes;const size_t bank=ZcsContentStore::BANK_BYTES;for(int variant=0;variant<8;++variant){bytes=good;switch(variant){case 0:bytes[bank+4]=2;break;case 1:bytes[bank+6]=17;break;case 2:word(bank+12,ZcsContentStore::CAPACITY+1);break;case 3:word(bank+48+36,UINT32_MAX);break;case 4:word(bank+48+40,UINT32_MAX);break;case 5:memset(bytes.data()+bank+48,'a',33);break;case 6:memcpy(bytes.data()+bank+48+44,bytes.data()+bank+48,33);break;case 7:word(bank+48+44+36,0);break;}refreshCrc(bank);ZcsContentStore reboot;CHECK(reboot.begin());CHECK(reboot.count()==1&&get(reboot,"old")=="A");CHECK(!reboot.find("new"));}}
void generationWrap(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"message","old"));word(8,UINT32_MAX);refreshCrc(0);ZcsContentStore latest;CHECK(latest.begin());CHECK(latest.generation()==UINT32_MAX);CHECK(put(latest,"message","new"));CHECK(latest.generation()==0);ZcsContentStore reboot;CHECK(reboot.begin());CHECK(get(reboot,"message")=="new");CHECK(reboot.remove("message"));CHECK(reboot.count()==0&&reboot.usedBytes()==0);ZcsContentStore empty;CHECK(empty.begin()&&empty.count()==0);}
void silentCorruption(){reset();ZcsContentStore s;CHECK(s.begin());CHECK(put(s,"message","old"));const auto initial=bytes;for(int which=0;which<3;++which){bytes=initial;corruptCall=-1;ZcsContentStore f;CHECK(f.begin());CHECK(f.beginPut("message",3,digest("new").c_str()));if(which==0)corruptCall=calls+1;CHECK(f.write(reinterpret_cast<const uint8_t*>("new"),3));if(which==1)corruptCall=calls+2;if(which==2)corruptCall=calls+4;CHECK(!f.finish());corruptCall=-1;ZcsContentStore reboot;CHECK(reboot.begin());CHECK(get(reboot,"message")=="old");}}
void unknownData(){reset();std::fill(bytes.begin(),bytes.end(),0xa5);const auto original=bytes;ZcsContentStore s;CHECK(s.begin());CHECK(s.available()&&s.count()==0);CHECK(bytes==original&&mutations==0);}

int main(){CHECK(digest("abc")=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");basic();bounds();uploadFailures();capacity();corruption();cuts();absent();forgedHeaders();generationWrap();silentCorruption();unknownData();std::cout<<"Content store: "<<checks<<" assertions passed\n";}
